                                                  alt="Selected"
                                                  className="h-40 w-40 object-contain" />
                                                  <div className="flex gap-3 mt-2 justify-center">
                                                    <svg
                                                        onClick={() => openMediaLibrary(slider.id, "urlIcon")}
                                                        xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="size-8 hover:text-red-700 ">
                                                      <path stroke-linecap="round" stroke-linejoin="round" d="M9 8.25H7.5a2.25 2.25 0 0 0-2.25 2.25v9a2.25 2.25 0 0 0 2.25 2.25h9a2.25 2.25 0 0 0 2.25-2.25v-9a2.25 2.25 0 0 0-2.25-2.25H15m0-3-3-3m0 0-3 3m3-3V15" />
                                                    </svg>
                                                    <svg
                                                        // onClick={() => setSelectedImage("")}
                                                        onClick={() => handleImageSelect("", slider.id, "urlIcon")}
                                                        xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="size-8 hover:text-red-700">
                                                      <path stroke-linecap="round" stroke-linejoin="round" d="m14.74 9-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 0 1-2.244 2.077H8.084a2.25 2.25 0 0 1-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 0 0-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 0 1 3.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 0 0-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 0 0-7.5 0" />
                                                    </svg>
                                                  </div>
                                              </div>
                                            ) : (
                                              <div
                                                // onClick={openMediaLibrary}
                                                onClick={() => openMediaLibrary(slider.id, "urlIcon")}
                                                className="flex flex-col items-center justify-center pt-5 pb-6 ">
                                              <svg
                                                  className="w-8 h-8 mb-4 text-gray-500"
                                                  aria-hidden="true"
                                                  xmlns="http://www.w3.org/2000/svg"
                                                  fill="none"
                                                  viewBox="0 0 20 16"
                                              >
                                                  <path
                                                      stroke="currentColor"
                                                      strokeLinecap="round"
                                                      strokeLinejoin="round"
                                                      strokeWidth="2"
                                                      d="M13 13h3a3 3 0 0 0 0-6h-.025A5.56 5.56 0 0 0 16 6.5 5.5 5.5 0 0 0 5.207 5.021C5.137 5.017 5.071 5 5 5a4 4 0 0 0 0 8h2.167M10 15V6m0 0L8 8m2-2 2 2"
                                                  />
                                              </svg>
                                              <p className="mb-2 text-sm text-gray-500">
                                                  <span className="font-semibold">Click to upload image</span>
                                              </p>
                                          </div>
                                            )}
                                          </label>
                                        </div>
                                      </div>
                                      {isMediaLibraryOpen && (
                                        <MediaLibraryModal
                                          onSelect={(imageUrl) => handleImageSelect(imageUrl, currentSliderId, currentField)}
                                          onClose={() => setMediaLibraryOpen(false)}
                                        />
                                      )} */}
                                    </div>
                                  </details>
                                </li>
                              )}
                            </Draggable>
                          ))}
                        </ul>
                        <a
                          className="flex items-center p-3 text-sm font-medium text-blue-600 border-t border rounded-b-lg bg-gray-50  hover:bg-gray-100  hover:underline"
                          onClick={handleAddSlider}
                        >
                          <svg
                            xmlns="http://www.w3.org/2000/svg"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke-width="1.5"
                            stroke="currentColor"
                            className="size-6 mr-2"
                          >
                            <path
                              stroke-linecap="round"
                              stroke-linejoin="round"
                              d="M12 9v6m3-3H9m12 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z"
                            />
                          </svg>
                          Add new item
                        </a>
                      </div>
                    )}
                  </Droppable>
                </DragDropContext>
              </details>
            </ul>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Slider;
